func bestQuote(vendors: [Vendor]) async throws -> Quote {
    try await withThrowingTaskGroup(of: Quote.self) { group in
        for v in vendors { group.addTask { try await ask(v) } }
        var quotes: [Quote] = []
        for try await q in group { quotes.append(q) }   // all children done
        return quotes.min { $0.rate < $1.rate }!        // merge
    }
}
